<template>
  <view class="page">
    <view class="nav"><button class="back" aria-label="返回" @tap="goBack">‹</button><text>当前时刻</text><button class="help" aria-label="轻断食说明" @tap="showTips = !showTips">?</button></view>
    <view class="calendar"><view v-for="day in calendar" :key="day.date" class="cal-day"><text>{{ day.week }}</text><text :class="{ selected: day.date === today }">{{ day.day }}</text></view></view>
    <view class="main-card">
      <view class="card-head"><view><text class="card-title">当日计划 · {{ plan.mode }}</text><text class="card-caption">{{ statusTitle }}</text></view><button class="edit" @tap="settingsVisible = true">设置提醒</button></view>
      <view class="timeline"><view><text>计划开始</text><strong>{{ plan.eatingEnd }}</strong></view><view class="timeline-line"><text>{{ fastHours }} 小时断食</text></view><view class="align-right"><text>计划结束</text><strong>{{ plan.eatingStart }}</strong></view></view>
      <view class="ring-wrap"><view class="ring" :style="{ '--progress': `${progressValue * 360}deg` }"><view class="ring-inner"><text class="ring-label">{{ isEating ? '正在用餐' : '正在断食' }}</text><strong>{{ remaining }}</strong><text class="ring-caption">{{ plan.active ? '今日已开始' : '尚未开始' }}</text></view></view></view>
      <view class="primary-actions"><button :disabled="plan.active" @tap="startFast">{{ plan.active ? '今日已开始' : '开始今天的断食' }}</button><button class="outline" :disabled="!plan.active" @tap="finishFast">结束并记录</button></view>
      <view class="legend"><view><i class="fast-dot" />断食计划</view><view><i class="eat-dot" />用餐计划</view><button class="checkin" @tap="checkin">{{ checkedToday ? '已用餐打卡' : '用餐打卡' }}</button></view>
      <view class="timebar"><text>{{ plan.eatingStart }}</text><view><i class="fast-segment" /><i class="eat-segment" /><i class="fast-segment" /></view><text>{{ plan.eatingEnd }}</text></view>
      <text class="note">{{ checkedToday ? '今天的用餐记录已记下' : '今日还没有打卡，不统计时长数据' }}</text>
