  </view>
</template>
<script setup lang="ts">
import { computed, ref } from 'vue';
import { onShow } from '@dcloudio/uni-app';
import { durationMinutes, formatRemaining, isEatingNow, loadFastingPlan, localDate, phaseProgress, saveFastingPlan, toggleFasting, type FastingMode } from '../../features/fasting/fasting-store.js';
const today = localDate(); const plan = ref(loadFastingPlan()); const now = ref(new Date()); const showTips = ref(false); const settingsVisible = ref(false); const modes: FastingMode[] = ['16:8', '14:10', '12:12'];
const calendar = computed(() => Array.from({ length: 7 }, (_, index) => { const date = new Date(); date.setDate(date.getDate() - (date.getDay() || 7) + 1 + index); return { date: new Date(date.getTime() - date.getTimezoneOffset() * 60000).toISOString().slice(0, 10), day: date.getDate(), week: ['日', '一', '二', '三', '四', '五', '六'][date.getDay()] }; }));
const progressValue = computed(() => phaseProgress(plan.value, now.value)); const remaining = computed(() => formatRemaining(plan.value, now.value)); const fastHours = computed(() => 24 - Math.round(durationMinutes(plan.value) / 60)); const isEating = computed(() => isEatingNow(plan.value, now.value)); const checkedToday = computed(() => plan.value.checkins.includes(today)); const statusTitle = computed(() => plan.value.active ? (isEating.value ? '把握舒服的用餐时间' : '给身体一段安静时间') : '准备好后，从一个温和的开始');
function refresh() { plan.value = loadFastingPlan(); now.value = new Date(); } function startFast() { plan.value = saveFastingPlan({ active: true, startedAt: new Date().toISOString() }); } function finishFast() { plan.value = saveFastingPlan({ active: false, endedAt: new Date().toISOString() }); } function checkin() { plan.value = toggleFasting(today); } function selectMode(mode: FastingMode) { const hours = Number(mode.split(':')[0]); const endHour = (Number(plan.value.eatingStart.slice(0, 2)) + 24 - hours) % 24; plan.value = saveFastingPlan({ mode, eatingEnd: `${String(endHour).padStart(2, '0')}:00` }); } function setStart(event: { detail: { value: string } }) { plan.value = saveFastingPlan({ eatingStart: event.detail.value }); } function setEnd(event: { detail: { value: string } }) { plan.value = saveFastingPlan({ eatingEnd: event.detail.value }); } function goBack() { uni.navigateBack(); } onShow(refresh);
</script>
